     1→/**
     2→ * ════════════════════════════════════════════════════════════════════
     3→ * Generics Resolution Engine
     4→ *
     5→ * Generic 선언 추출, Type Parameter 제약, 인스턴스화, Variance 분석
     6→ * ════════════════════════════════════════════════════════════════════
     7→ */
     8→
     9→/**
    10→ * Type Parameter 정의
    11→ */
    12→export interface TypeParameter {
    13→  name: string;                   // "T", "K", "V"
    14→  constraint?: string;            // "T extends number"
    15→  default?: string;               // "T = string"
    16→  variance: 'covariant' | 'contravariant' | 'invariant';
    17→}
    18→
    19→/**
    20→ * Generic Signature
    21→ */
    22→export interface GenericSignature {
    23→  name: string;
    24→  typeParams: TypeParameter[];
    25→  signature: string;
    26→  instantiations: GenericInstantiation[];
    27→  confidence: number;
    28→}
    29→
    30→/**
    31→ * Generic Instantiation
    32→ */
    33→export interface GenericInstantiation {
    34→  typeArgs: Map<string, string>;  // T → number
    35→  resultType: string;
    36→  confidence: number;
    37→  source: 'explicit' | 'inferred';
    38→  reasoning: string[];
    39→}
    40→
    41→/**
    42→ * Generics Resolution 결과
    43→ */
    44→export interface GenericsResolutionResult {
    45→  generics: Map<string, GenericSignature>;
    46→  instantiations: GenericInstantiation[];
    47→  resolutionSuccess: number;      // 0.0-1.0
    48→  reasoning: string[];
    49→}
    50→
    51→/**
    52→ * Generics Resolution Engine
    53→ */
    54→export class GenericsResolutionEngine {
    55→  /**
    56→   * 메인 빌드 메서드
    57→   */
    58→  build(code: string): GenericsResolutionResult {
    59→    const result: GenericsResolutionResult = {
    60→      generics: new Map(),
    61→      instantiations: [],
    62→      resolutionSuccess: 0,
    63→      reasoning: []
    64→    };
    65→
    66→    // Step 1: Generic 선언 추출
    67→    this.extractGenericDeclarations(code, result);
    68→
    69→    // Step 2: Type Parameter 제약 추출
    70→    this.extractTypeParameters(code, result);
    71→
    72→    // Step 3: Instantiation 추론
    73→    this.inferInstantiations(code, result);
    74→
    75→    // Step 4: Resolution 성공률 계산
    76→    this.calculateResolutionSuccess(result);
    77→
    78→    return result;
    79→  }
    80→
    81→  /**
    82→   * Generic 선언 추출
    83→   */
    84→  private extractGenericDeclarations(code: string, result: GenericsResolutionResult): void {
    85→    // 패턴: Type<T>, Map<K,V>, etc.
    86→    const genericPattern = /(\w+)<([A-Z][a-zA-Z0-9]*(?:\s*,\s*[A-Z][a-zA-Z0-9]*)*)>/g;
    87→    let match;
    88→    const processed = new Set<string>();
    89→
    90→    while ((match = genericPattern.exec(code)) !== null) {
    91→      const typeName = match[1];
    92→      const typeParamsStr = match[2];
    93→
    94→      if (processed.has(typeName)) continue;
    95→      processed.add(typeName);
    96→
    97→      const typeParamNames = typeParamsStr.split(',').map(s => s.trim());
    98→      const typeParams: TypeParameter[] = typeParamNames.map(name => ({
    99→        name,
   100→        variance: this.inferVariance(typeName),
   101→      }));
   102→
   103→      const signature: GenericSignature = {
   104→        name: typeName,
   105→        typeParams,
   106→        signature: match[0],
   107→        instantiations: [],
   108→        confidence: 0.85,
   109→      };
   110→
   111→      result.generics.set(typeName, signature);
   112→      result.reasoning.push(`Generic type detected: ${match[0]}`);
   113→    }
   114→  }
   115→
   116→  /**
   117→   * Type Parameter 제약 추출
   118→   */
   119→  private extractTypeParameters(code: string, result: GenericsResolutionResult): void {
   120→    // extends 제약
   121→    const extendsPattern = /(\w+)\s+extends\s+([A-Za-z0-9<>,\s]+)/g;
   122→    let match;
   123→
   124→    while ((match = extendsPattern.exec(code)) !== null) {
   125→      const paramName = match[1];
   126→      const constraint = match[2].trim();
   127→
   128→      // 모든 generic에서 이 파라미터를 찾아 제약 추가
   129→      for (const [_, sig] of result.generics.entries()) {
   130→        const param = sig.typeParams.find(p => p.name === paramName);
   131→        if (param) {
   132→          param.constraint = constraint;
   133→          result.reasoning.push(`Type constraint: ${paramName} extends ${constraint}`);
   134→        }
   135→      }
   136→    }
   137→  }
   138→
   139→  /**
   140→   * Generic 인스턴시이션 추론
   141→   */
   142→  private inferInstantiations(code: string, result: GenericsResolutionResult): void {
   143→    // 명시적 인스턴시이션: array<number>, Map<string, number>
   144→    const instantPattern = /(\w+)<([^>]+)>/g;
   145→    let match;
   146→
   147→    while ((match = instantPattern.exec(code)) !== null) {
   148→      const typeName = match[1];
   149→      const typeArgsStr = match[2];
   150→
   151→      if (!result.generics.has(typeName)) continue;
   152→
   153→      const sig = result.generics.get(typeName)!;
   154→      const typeArgs = this.parseTypeArgs(typeArgsStr);
   155→      const typeArgMap = new Map<string, string>();
   156→
   157→      // Type parameters에 인수 매핑
   158→      for (let i = 0; i < sig.typeParams.length && i < typeArgs.length; i++) {
   159→        typeArgMap.set(sig.typeParams[i].name, typeArgs[i]);
   160→      }
   161→
   162→      const resultType = typeName + '<' + typeArgs.join(', ') + '>';
   163→      const instantiation: GenericInstantiation = {
   164→        typeArgs: typeArgMap,
   165→        resultType,
   166→        confidence: 0.85,
   167→        source: 'explicit',
   168→        reasoning: [`Explicit instantiation: ${resultType}`]
   169→      };
   170→
   171→      result.instantiations.push(instantiation);
   172→      sig.instantiations.push(instantiation);
   173→    }
   174→  }
   175→
   176→  /**
   177→   * Type Arguments 파싱 (중첩 지원)
   178→   */
   179→  private parseTypeArgs(typeArgsStr: string): string[] {
   180→    const args: string[] = [];
   181→    let current = '';
   182→    let depth = 0;
   183→
   184→    for (const char of typeArgsStr) {
   185→      if (char === '<') {
   186→        depth++;
   187→        current += char;
   188→      } else if (char === '>') {
   189→        depth--;
   190→        current += char;
   191→      } else if (char === ',' && depth === 0) {
   192→        args.push(current.trim());
   193→        current = '';
   194→      } else {
   195→        current += char;
   196→      }
   197→    }
   198→
   199→    if (current) {
   200→      args.push(current.trim());
   201→    }
   202→
   203→    return args;
   204→  }
   205→
   206→  /**
   207→   * Resolution 성공률 계산
   208→   */
   209→  private calculateResolutionSuccess(result: GenericsResolutionResult): void {
   210→    if (result.generics.size === 0) {
   211→      result.resolutionSuccess = 0;
   212→      return;
   213→    }
   214→
   215→    let instantiatedCount = 0;
   216→    for (const sig of result.generics.values()) {
   217→      if (sig.instantiations.length > 0) instantiatedCount++;
   218→    }
   219→
   220→    result.resolutionSuccess = instantiatedCount / result.generics.size;
   221→    result.reasoning.push(
   222→      `Resolution success: ${instantiatedCount}/${result.generics.size} = ${(result.resolutionSuccess * 100).toFixed(1)}%`
   223→    );
   224→  }
   225→
   226→  /**
   227→   * Variance 추론
   228→   */
   229→  private inferVariance(typeName: string): 'covariant' | 'contravariant' | 'invariant' {
   230→    // array, list, vector는 covariant
   231→    if (['array', 'list', 'vector', 'tuple'].includes(typeName.toLowerCase())) {
   232→      return 'covariant';
   233→    }
   234→
   235→    // function은 contravariant
   236→    if (typeName.toLowerCase() === 'function') {
   237→      return 'contravariant';
   238→    }
   239→
   240→    // 기본값은 invariant
   241→    return 'invariant';
   242→  }
   243→
   244→  /**
   245→   * 특정 타입의 인스턴시이션 조회
   246→   */
   247→  getInstantiations(result: GenericsResolutionResult, typeName: string): GenericInstantiation[] {
   248→    const sig = result.generics.get(typeName);
   249→    return sig?.instantiations || [];
   250→  }
   251→
   252→  /**
   253→   * Generic signature 조회
   254→   */
   255→  getSignature(result: GenericsResolutionResult, typeName: string): GenericSignature | null {
   256→    return result.generics.get(typeName) || null;
   257→  }
   258→
   259→  /**
   260→   * 모든 generic 조회
   261→   */
   262→  getAllGenerics(result: GenericsResolutionResult): GenericSignature[] {
   263→    return Array.from(result.generics.values());
   264→  }
   265→}
   266→

