     1→/**
     2→ * FreeLang Compiler
     3→ * 소스코드 → AST → 바이트코드 변환
     4→ */
     5→
     6→import { ISAGenerator, Program, Assignment, BinaryOp, NumberLiteral } from './isa-generator';
     7→
     8→/**
     9→ * 간단한 Lexer (토큰화)
    10→ */
    11→class Lexer {
    12→  private source: string;
    13→  private position: number = 0;
    14→
    15→  constructor(source: string) {
    16→    this.source = source;
    17→  }
    18→
    19→  tokenize(): Token[] {
    20→    const tokens: Token[] = [];
    21→
    22→    while (this.position < this.source.length) {
    23→      this.skipWhitespace();
    24→
    25→      if (this.position >= this.source.length) break;
    26→
    27→      const ch = this.source[this.position];
    28→
    29→      // 숫자
    30→      if (this.isDigit(ch)) {
    31→        tokens.push(this.readNumber());
    32→      }
    33→      // 식별자/키워드
    34→      else if (this.isLetter(ch)) {
    35→        tokens.push(this.readIdentifier());
    36→      }
    37→      // 연산자
    38→      else if (ch === '+') {
    39→        tokens.push({ type: 'PLUS', value: '+' });
    40→        this.position++;
    41→      } else if (ch === '-') {
    42→        tokens.push({ type: 'MINUS', value: '-' });
    43→        this.position++;
    44→      } else if (ch === '*') {
    45→        tokens.push({ type: 'MUL', value: '*' });
    46→        this.position++;
    47→      } else if (ch === '/') {
    48→        tokens.push({ type: 'DIV', value: '/' });
    49→        this.position++;
    50→      } else if (ch === '=') {
    51→        tokens.push({ type: 'ASSIGN', value: '=' });
    52→        this.position++;
    53→      } else if (ch === '(') {
    54→        tokens.push({ type: 'LPAREN', value: '(' });
    55→        this.position++;
    56→      } else if (ch === ')') {
    57→        tokens.push({ type: 'RPAREN', value: ')' });
    58→        this.position++;
    59→      } else if (ch === '{') {
    60→        tokens.push({ type: 'LBRACE', value: '{' });
    61→        this.position++;
    62→      } else if (ch === '}') {
    63→        tokens.push({ type: 'RBRACE', value: '}' });
    64→        this.position++;
    65→      } else if (ch === ';') {
    66→        tokens.push({ type: 'SEMICOLON', value: ';' });
    67→        this.position++;
    68→      } else {
    69→        this.position++;
    70→      }
    71→    }
    72→
    73→    tokens.push({ type: 'EOF', value: '' });
    74→    return tokens;
    75→  }
    76→
    77→  private skipWhitespace(): void {
    78→    while (
    79→      this.position < this.source.length &&
    80→      /\s/.test(this.source[this.position])
    81→    ) {
    82→      this.position++;
    83→    }
    84→  }
    85→
    86→  private isDigit(ch: string): boolean {
    87→    return /\d/.test(ch);
    88→  }
    89→
    90→  private isLetter(ch: string): boolean {
    91→    return /[a-zA-Z_]/.test(ch);
    92→  }
    93→
    94→  private readNumber(): Token {
    95→    let value = '';
    96→    while (
    97→      this.position < this.source.length &&
    98→      this.isDigit(this.source[this.position])
    99→    ) {
   100→      value += this.source[this.position];
   101→      this.position++;
   102→    }
   103→    return { type: 'NUMBER', value: parseInt(value) };
   104→  }
   105→
   106→  private readIdentifier(): Token {
   107→    let value = '';
   108→    while (
   109→      this.position < this.source.length &&
   110→      (this.isLetter(this.source[this.position]) ||
   111→        this.isDigit(this.source[this.position]))
   112→    ) {
   113→      value += this.source[this.position];
   114→      this.position++;
   115→    }
   116→    return { type: 'IDENTIFIER', value };
   117→  }
   118→}
   119→
   120→interface Token {
   121→  type: string;
   122→  value: any;
   123→}
   124→
   125→/**
   126→ * 간단한 Parser (구문 분석)
   127→ */
   128→class Parser {
   129→  private tokens: Token[];
   130→  private position: number = 0;
   131→
   132→  constructor(tokens: Token[]) {
   133→    this.tokens = tokens;
   134→  }
   135→
   136→  parse(): Program {
   137→    const statements: any[] = [];
   138→
   139→    while (!this.isAtEnd()) {
   140→      const stmt = this.parseStatement();
   141→      if (stmt) statements.push(stmt);
   142→    }
   143→
   144→    return { type: 'Program', statements };
   145→  }
   146→
   147→  private parseStatement(): any {
   148→    if (this.match('LBRACE')) {
   149→      return this.parseBlock();
   150→    }
   151→
   152→    const expr = this.parseExpression();
   153→
   154→    if (this.match('ASSIGN')) {
   155→      const value = this.parseExpression();
   156→      this.match('SEMICOLON');
   157→      return { type: 'Assignment', target: expr.name || expr.value, value };
   158→    }
   159→
   160→    this.match('SEMICOLON');
   161→    return expr;
   162→  }
   163→
   164→  private parseBlock(): any {
   165→    const statements: any[] = [];
   166→    while (!this.check('RBRACE') && !this.isAtEnd()) {
   167→      const stmt = this.parseStatement();
   168→      if (stmt) statements.push(stmt);
   169→    }
   170→    this.match('RBRACE');
   171→    return { type: 'Block', statements };
   172→  }
   173→
   174→  private parseExpression(): any {
   175→    return this.parseAdditive();
   176→  }
   177→
   178→  private parseAdditive(): any {
   179→    let expr = this.parseMultiplicative();
   180→
   181→    while (this.match('PLUS', 'MINUS')) {
   182→      const op = this.previous().value;
   183→      const right = this.parseMultiplicative();
   184→      expr = { type: 'BinaryOp', op, left: expr, right };
   185→    }
   186→
   187→    return expr;
   188→  }
   189→
   190→  private parseMultiplicative(): any {
   191→    let expr = this.parsePrimary();
   192→
   193→    while (this.match('MUL', 'DIV')) {
   194→      const op = this.previous().value;
   195→      const right = this.parsePrimary();
   196→      expr = { type: 'BinaryOp', op, left: expr, right };
   197→    }
   198→
   199→    return expr;
   200→  }
   201→
   202→  private parsePrimary(): any {
   203→    if (this.match('NUMBER')) {
   204→      return { type: 'NumberLiteral', value: this.previous().value };
   205→    }
   206→
   207→    if (this.match('IDENTIFIER')) {
   208→      const name = this.previous().value;
   209→      if (this.match('LPAREN')) {
   210→        // 함수 호출
   211→        const args: any[] = [];
   212→        while (!this.check('RPAREN') && !this.isAtEnd()) {
   213→          args.push(this.parseExpression());
   214→          if (!this.check('RPAREN')) this.match('COMMA');
   215→        }
   216→        this.match('RPAREN');
   217→        return { type: 'FunctionCall', name, args };
   218→      }
   219→      return { type: 'Identifier', name };
   220→    }
   221→
   222→    if (this.match('LPAREN')) {
   223→      const expr = this.parseExpression();
   224→      this.match('RPAREN');
   225→      return expr;
   226→    }
   227→
   228→    throw new Error(`Unexpected token: ${this.peek().type}`);
   229→  }
   230→
   231→  private match(...types: string[]): boolean {
   232→    for (const type of types) {
   233→      if (this.check(type)) {
   234→        this.advance();
   235→        return true;
   236→      }
   237→    }
   238→    return false;
   239→  }
   240→
   241→  private check(type: string): boolean {
   242→    if (this.isAtEnd()) return false;
   243→    return this.peek().type === type;
   244→  }
   245→
   246→  private advance(): Token {
   247→    if (!this.isAtEnd()) this.position++;
   248→    return this.previous();
   249→  }
   250→
   251→  private isAtEnd(): boolean {
   252→    return this.peek().type === 'EOF';
   253→  }
   254→
   255→  private peek(): Token {
   256→    return this.tokens[this.position];
   257→  }
   258→
   259→  private previous(): Token {
   260→    return this.tokens[this.position - 1];
   261→  }
   262→}
   263→
   264→/**
   265→ * 전체 Compiler 클래스
   266→ */
   267→export class Compiler {
   268→  /**
   269→   * 소스코드를 바이트코드로 컴파일
   270→   */
   271→  static compile(source: string): number[] {
   272→    // Step 1: Lexer (토큰화)
   273→    const lexer = new Lexer(source);
   274→    const tokens = lexer.tokenize();
   275→
   276→    // Step 2: Parser (AST 생성)
   277→    const parser = new Parser(tokens);
   278→    const ast = parser.parse() as Program;
   279→
   280→    // Step 3: ISA Generator (바이트코드 생성)
   281→    const generator = new ISAGenerator();
   282→    const bytecode = generator.generate(ast);
   283→
   284→    return bytecode;
   285→  }
   286→}
   287→
   288→// Export
   289→export { Lexer, Parser, ISAGenerator };
   290→

