     1→/**
     2→ * Phase 18: IR Generator
     3→ * Transforms AST → IR instruction array for VM execution
     4→ *
     5→ * Day 1-2 MVP: Literals + Arithmetic operations
     6→ */
     7→
     8→import { Inst, Op, AIIntent } from '../types';
     9→import { Module, ImportStatement, ExportStatement, FunctionStatement, VariableDeclaration } from '../parser/ast';
    10→
    11→export interface ASTNode {
    12→  type: string;
    13→  [key: string]: any;
    14→}
    15→
    16→/**
    17→ * Phase 4 Step 5: Module linking context
    18→ * 모듈 간 심볼 연결을 위한 컨텍스트
    19→ */
    20→export interface ModuleLinkContext {
    21→  importedSymbols: Map<string, string>;  // 심볼명 → 임포트 경로
    22→  exportedSymbols: Map<string, string>;  // 심볼명 → 타입
    23→  moduleResolver?: any;                   // ModuleResolver 인스턴스
    24→}
    25→
    26→export class IRGenerator {
    27→  private indexVarCounter = 0;  // For generating unique index variables
    28→  private tempVarCounter = 0;   // For generating temporary array variables
    29→  private moduleLinkContext?: ModuleLinkContext;  // Phase 4 Step 5: Module linking
    30→  private localScope: Set<string> = new Set();  // Function parameter scope tracking
    31→
    32→  /**
    33→   * AST → IR instructions
    34→   * Example: BinaryOp('+', 1, 2) → [PUSH 1, PUSH 2, ADD, HALT]
    35→   *
    36→   * @param ast AST node to compile
    37→   * @param localScope Optional array of parameter names for function scope
    38→   */
    39→  /**
    40→   * Self-Monitoring Kernel: @monitor 어노테이션 함수 body IR 래핑
    41→   *
    42→   * 동작:
    43→   * 1. PUSH fnName → CALL insight_enter  (함수 진입 기록)
    44→   * 2. 원본 body IR (RET 직전에 insight_exit 주입)
    45→   * 3. 마지막 HALT 앞 insight_exit 보장
    46→   *
    47→   * 오버헤드: PUSH + CALL 2개 = ~50ns (TSC 측정 자체보다 낮음)
    48→   */
    49→  wrapWithMonitoring(bodyIR: Inst[], fnName: string): Inst[] {
    50→    const result: Inst[] = [];
    51→
    52→    // 진입 기록: insight_enter(fnName)
    53→    // insight_enter는 null 반환 → VM이 스택에 push하지 않음 → POP 불필요
    54→    result.push({ op: Op.STR_NEW, arg: fnName });
