   127→   */
   128→  static registerStruct(
   129→    name: string,
   130→    fields: Array<{ name: string; typeName: string }>,
   131→    typeParams?: GenericTypeParam[]
   132→  ): void {
   133→    this.initialize();
   134→
   135→    const layoutFields: FieldLayout[] = [];
   136→    let offset = 0;
   137→
   138→    for (const field of fields) {
   139→      const isNullable = field.typeName.endsWith('?');
   140→      const baseTypeName = isNullable ? field.typeName.slice(0, -1) : field.typeName;
   141→      const resolved = this.resolve(baseTypeName);
   142→      const fieldSize = (resolved?.size ?? 8) + (isNullable ? 1 : 0); // nullable → +1 null tag
   143→
   144→      // 정렬 패딩 계산
   145→      const align = resolved?.alignment ?? 8;
   146→      const padding = (align - (offset % align)) % align;
   147→      offset += padding;
   148→
   149→      layoutFields.push({
   150→        name: field.name,
   151→        typeName: field.typeName,
   152→        offset,
   153→        size: fieldSize,
   154→        isNullable,
   155→      });
   156→
   157→      offset += fieldSize;
   158→    }
   159→
   160→    // 구조체 전체 크기는 최대 정렬의 배수로 올림
   161→    const maxAlign = layoutFields.reduce((m, f) => {
   162→      const ft = this.resolve(f.typeName.replace('?', ''));
   163→      return Math.max(m, ft?.alignment ?? 8);
   164→    }, 1);
   165→
   166→    const totalSize = Math.ceil(offset / maxAlign) * maxAlign;
   167→
   168→    this.registry.set(name, {
   169→      name,
   170→      kind: typeParams && typeParams.length > 0 ? 'generic' : 'struct',
   171→      size: totalSize,
   172→      alignment: maxAlign,
   173→      fields: layoutFields,
   174→      typeParams,
   175→    });
   176→  }
