   183→function typeToString(t: Type): string {
   184→  switch (t.kind) {
   185→    case "i32": case "i64": case "f64": case "bool": case "string": case "void":
   186→      return t.kind;
   187→    case "array": return `[${typeToString(t.element)}]`;
   188→    case "channel": return `channel<${typeToString(t.element)}>`;
   189→    case "option": return `Option<${typeToString(t.element)}>`;
   190→    case "result": return `Result<${typeToString(t.ok)}, ${typeToString(t.err)}>`;
   191→    case "struct": {
   192→      const fields = [...t.fields.entries()].map(([k, v]) => `${k}: ${typeToString(v)}`).join(", ");
   193→      return `{ ${fields} }`;
   194→    }
   195→    case "fn": {
   196→      const paramStr = t.params.map(typeToString).join(", ");
   197→      return `fn(${paramStr}) -> ${typeToString(t.returnType)}`;
   198→    }
   199→    // 2-D: Union + type_param 출력 추가
   200→    case "union": {
   201→      const unionT = t as { kind: "union"; types: Type[] };
   202→      return unionT.types.map(typeToString).join(" | ");
   203→    }
   204→    case "type_param":
   205→      return (t as any).name;
   206→    case "unknown": return "unknown";
   207→  }
   208→}
   209→
   210→function annotationToType(a: TypeAnnotation, structDefs: Map<string, Type> = new Map()): Type {
   211→  switch (a.kind) {
   212→    case "i32": return { kind: "i32" };
   213→    case "i64": return { kind: "i64" };
   214→    case "f64": return { kind: "f64" };
   215→    case "bool": return { kind: "bool" };
   216→    case "string": return { kind: "string" };
   217→    case "void": return { kind: "void" };
   218→    case "any": return { kind: "any" };
   219→    case "array": return { kind: "array", element: annotationToType(a.element, structDefs) };
   220→    case "channel": return { kind: "channel", element: annotationToType(a.element, structDefs) };
   221→    case "option": return { kind: "option", element: annotationToType(a.element, structDefs) };
   222→    case "result": return { kind: "result", ok: annotationToType(a.ok, structDefs), err: annotationToType(a.err, structDefs) };
   223→    case "struct_ref": {
   224→      const structType = structDefs.get(a.name);
   225→      return structType || { kind: "unknown" };
   226→    }
   227→    case "fn": {
   228→      const params = a.params.map(p => annotationToType(p, structDefs));
   229→      const returnType = annotationToType(a.returnType, structDefs);
   230→      return { kind: "fn", params, returnType };
   231→    }
   232→    // 2-D: Union + generic_ref 처리 추가
   233→    case "union": {
   234→      const annUnion = a as { kind: "union"; types: TypeAnnotation[] };
   235→      return { kind: "union", types: annUnion.types.map(t => annotationToType(t, structDefs)) };
   236→    }
   237→    case "generic_ref": {
   238→      // T, Option<T> 같은 generic 참조 → type_param으로 취급
   239→      const annGen = a as { kind: "generic_ref"; name: string; typeArgs?: TypeAnnotation[] };
   240→      return { kind: "type_param", name: annGen.name };
   241→    }
   242→  }
   243→}
